import{_ as t,o,c as a,a6 as r}from"./chunks/framework.BHBQfcoO.js";const m=JSON.parse('{"title":"LCARdS Theme Profiles for HA-LCARS","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/ha-lcars-theme-profiles.md","filePath":"configuration/ha-lcars-theme-profiles.md"}'),l={name:"configuration/ha-lcars-theme-profiles.md"};function d(s,e,i,n,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="lcards-theme-profiles-for-ha-lcars" tabindex="-1">LCARdS Theme Profiles for HA-LCARS <a class="header-anchor" href="#lcards-theme-profiles-for-ha-lcars" aria-label="Permalink to &quot;LCARdS Theme Profiles for HA-LCARS&quot;">​</a></h1><p>LCARdS ships a set of ready-made theme profiles designed to be used alongside the <a href="https://github.com/th3jesta/ha-lcars" target="_blank" rel="noreferrer"><strong>HA-LCARS</strong></a> community theme.</p><ul><li>Uses the <strong>LCARdS colour palette</strong> (<code>--lcards-*</code> variables) that are provided automatically by the integration.</li><li>The <strong>HA core colour tokens</strong> (<code>--ha-color-*</code>) which are used by stock Home Assistant components are remapped to LCARdS palette entries. This helps bring more theme consistency across across the UI.</li><li>All variables are assigned dynamic HA-LCARS/LCARdS palette references, meaning alert-mode hue rotations and light/dark mode switches propagate automatically.</li></ul><hr><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>You need <strong>HA-LCARS</strong> installed before applying these profiles. Follow the installation guide on the <a href="https://github.com/th3jesta/ha-lcars" target="_blank" rel="noreferrer">HA-LCARS repository</a> first.</p><hr><h2 id="profile-yaml" tabindex="-1">Profile YAML <a class="header-anchor" href="#profile-yaml" aria-label="Permalink to &quot;Profile YAML&quot;">​</a></h2><p>Download or copy from the file below and paste at the end of your <code>themes.yaml</code>:</p><p>→ <strong><a href="https://github.com/snootched/lcards/tree/main/yaml/theme/ha-lcars-lcards-themes.yaml" target="_blank" rel="noreferrer">ha-lcars-lcards-themes.yaml</a></strong></p><hr><h2 id="available-profiles" tabindex="-1">Available Profiles <a class="header-anchor" href="#available-profiles" aria-label="Permalink to &quot;Available Profiles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Profile name</th><th>Accent colour</th><th>Notes</th></tr></thead><tbody><tr><td><code>LCARS Picard [LCARdS Red Accent]</code></td><td>Orange/Red (<code>--lcards-orange-*</code>)</td><td>Primary accent mapped to the LCARdS orange family</td></tr><tr><td><code>LCARS Picard [LCARdS Blue Accent]</code></td><td>Blue (<code>--lcards-blue-*</code>)</td><td>Primary accent mapped to the LCARdS blue family</td></tr></tbody></table><p>Both profiles include independent <strong>light</strong> and <strong>dark</strong> mode sections and cover the full 11-shade HA core colour token range, plus HA&#39;s <code>on-*</code>/<code>fill-*</code>/<code>border-*</code>/<code>surface-*</code> semantic layer (the vars behind buttons, chips, form fields, and dialogs).</p><hr><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>The profiles are appended to the end of your existing HA-LCARS <code>themes.yaml</code> file. This is the standard HA-LCARS extension pattern; no existing theme entries are modified.</p><ol><li>Open your HA-LCARS <code>themes.yaml</code> file (typically <code>config/themes/ha-lcars/themes.yaml</code>).</li><li>Scroll to the <strong>very end</strong> of the file.</li><li>Copy the entire contents of the profile YAML file linked below and paste it after the last line.</li><li>Reload themes in Home Assistant: <strong>Developer Tools → YAML → Reload Themes</strong>, or call the <code>frontend.reload_themes</code> service.</li><li>Select the profile in <strong>Profile → Theme</strong> in the HA frontend.</li></ol><hr><h2 id="how-the-colour-mapping-works" tabindex="-1">How the Colour Mapping Works <a class="header-anchor" href="#how-the-colour-mapping-works" aria-label="Permalink to &quot;How the Colour Mapping Works&quot;">​</a></h2><h3 id="ha-core-colour-tokens" tabindex="-1">HA Core Colour Tokens <a class="header-anchor" href="#ha-core-colour-tokens" aria-label="Permalink to &quot;HA Core Colour Tokens&quot;">​</a></h3><p>Home Assistant&#39;s frontend exposes an 11-shade scale (05 → 95) for five colour families: <code>primary</code>, <code>neutral</code>, <code>orange</code>, <code>red</code>, and <code>green</code>. These are consumed by stock HA components. The profiles map each HA shade <strong>1:1</strong> to the matching stop on the <a href="./../core/themes/#lcards-css-colour-palette">LCARdS 11-stop palette scale</a>; LCARdS&#39;s own palette was expanded from its original 7 canon stops specifically so this mapping wouldn&#39;t need to lossily collapse multiple HA shades onto the same colour.</p><p>The family mapping differs per profile accent:</p><table tabindex="0"><thead><tr><th>HA family</th><th>Red Accent profile</th><th>Blue Accent profile</th></tr></thead><tbody><tr><td><code>primary</code></td><td><code>--lcards-orange-*</code></td><td><code>--lcards-blue-*</code></td></tr><tr><td><code>neutral</code></td><td><code>--lcards-gray-*</code></td><td><code>--lcards-gray-*</code></td></tr><tr><td><code>orange</code></td><td><code>--lcards-yellow-*</code></td><td><code>--lcards-yellow-*</code></td></tr><tr><td><code>red</code></td><td><code>--lcards-orange-*</code></td><td><code>--lcards-orange-*</code></td></tr><tr><td><code>green</code></td><td><code>--lcards-green-*</code></td><td><code>--lcards-green-*</code></td></tr></tbody></table><h3 id="semantic-tokens-text-on-fill-contrast" tabindex="-1">Semantic Tokens (text-on-fill contrast) <a class="header-anchor" href="#semantic-tokens-text-on-fill-contrast" aria-label="Permalink to &quot;Semantic Tokens (text-on-fill contrast)&quot;">​</a></h3><p>Remapping the shade scale alone isn&#39;t enough for readable text: HA computes button, chip, and form-field text colours (<code>--ha-color-on-*</code>) by referencing a fixed tone number within the same palette (e.g. &quot;text = tone 40 of whatever primary is&quot;), on the assumption that any colour a theme substitutes will still read clearly at that tone. That assumption doesn&#39;t hold equally for every hue: LCARdS&#39;s orange family has a narrower readable-lightness range than its blue family, which is why the Red Accent profile could otherwise generate low-contrast button text.</p><p>Both profiles now explicitly set the full <code>on-*</code>/<code>fill-*</code>/<code>border-*</code>/<code>surface-*</code> semantic layer, with every text/background pairing checked against real WCAG contrast math and corrected where HA&#39;s mechanical default would fail, rather than relying on the shade-scale remapping to produce readable results by chance. See <a href="./../development/ha-css-vars.html#layer-2-semantic-colour-tokens">ha-css-vars.md</a> for the full technical detail.</p><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="https://github.com/th3jesta/ha-lcars" target="_blank" rel="noreferrer">HA-LCARS repository</a></li><li><a href="./../core/themes/#lcards-css-colour-palette">LCARdS Colour Palette</a></li><li><a href="./../core/themes/">LCARdS Themes</a></li><li><a href="./../core/alert-mode.html">Alert Mode</a></li><li><a href="./../getting-started/installation.html">Installation</a></li></ul>',30)])])}const f=t(l,[["render",d]]);export{m as __pageData,f as default};
